function severity(affectedUsers, dataExposed) {
  if (dataExposed || affectedUsers > 10000) return 'P1 critical';
  if (affectedUsers > 100) return 'P2 high';
  return 'P3 low';
}
console.log(severity(500, false));
console.log(severity(50, true));

