function checklist(feature) {
  const base = ['validate input server-side', 'check auth on new endpoints', 'no secrets in diff'];
  if (feature === 'payments') base.push('threat-model money flows');
  if (feature === 'uploads') base.push('restrict file types and size');
  return base;
}
const items = checklist('payments');
items.forEach((item, i) => console.log((i + 1) + '. ' + item));

