const vulns = [
  { name: 'outdated lodash', sev: 2 },
  { name: 'SQL injection in search', sev: 5 },
  { name: 'verbose error page', sev: 1 },
];
vulns.sort((a, b) => b.sev - a.sev);
for (const v of vulns) console.log('P' + (6 - v.sev) + ' ' + v.name);

